exercise.referenceSolution:
struct Reader { virtual int read() const = 0; virtual ~Reader() = default; };
class ConstantReader : public Reader { int value_; public: explicit ConstantReader(int x) : value_(x) {} int read() const override { return value_; } };
int difference(const Reader& left,const Reader& right) { return left.read()-right.read(); }
int solve(int a,int b) { ConstantReader x{a},y{b}; return difference(x,y); }

